$history=find_by_sql("SELECT * FROM ti_amenazas_evaluaciones WHERE IdAmenaza=$id ORDER BY IdEvaluacion DESC");$risks=find_by_sql("SELECT IdRiesgo,Codigo,Escenario FROM sgsi_riesgos ORDER BY Codigo");include_once __DIR__.'/../../layouts/header.php';?>
