><label>Versión instalada</label><input name="VersionInstalada" class="form-control"></div><div class="form-group"><label>Análisis de aplicabilidad *</label><textarea name="Analisis" rows="3" class="form-control" required></textarea></div><div class="form-group"><label>Acción preventiva o correctiva</label><textarea name="Accion" rows="2" class="form-control"></textarea></div><div class="row"><div class="col-7 form-group"><label>Responsable</label><input name="Responsable" class="form-control" value="<?=ma_h(ma_user_name())?>"></div><div class="col-5 form-group"><label>Compromiso</label><input type="date" name="FechaCompromiso" class="form-control"></div></div><div class="form-group"><label>Evidencia / ticket / URL</label><input name="Evidencia" class="form-control"></div><div class="form-group"><label>Riesgo SGSI relacionado</label><select name="IdRiesgo" class="form-control"><option value="">Sin vincular</option><?php foreach($risks as $r):?><option value="<?=(int)$r['IdRiesgo']?>"><?=ma_h($r['Codigo'].' · '.$r['Escenario'])?></option><?php endforeach;?></select></div><button class="btn btn-info btn-block font-weight-bold">Guardar evaluación</button></form></div></div><div class="col-lg-7"><div class="card ta-card"><div class="card-header"><strong>Historial y evidencia</strong></div><div class="card-body"><?php foreach($history as $h):?><div class="border-bottom pb-3 mb-3"><div class="d-flex justify-content-between"><strong><?=ma_h($h['Aplica'].' · '.$h['Prioridad'])?></strong><small><?=ma_h($h['FechaEvaluacion'])?></small></div><span class="badge badge-info"><?=ma_h($h['Estado'])?></span><p class="mt-2 mb-1"><?=ma_h($h['Analisis'])?></p><div class="small text-muted"><?=ma_h($h['ActivosAfectados'])?> · <?=ma_h($h['Responsable'])?> · <?=ma_h($h['Evidencia'])?></div></div><?php endforeach;?><?php if(!$history):?><div class="text-muted text-center py-5">Todavía no se evaluó esta amenaza.</div><?php endif;?></div></div></div></div></div></section><?php include_once __